func groupAnagrams(_ strs: [String]) -> [[String]] {
    var groups: [[Int]: [String]] = [:]
    for s in strs {
        var key = [Int](repeating: 0, count: 26)
        for b in s.utf8 { key[Int(b - 97)] += 1 }
        groups[key, default: []].append(s)
    }
    return Array(groups.values)
}
